Member Description Constructor <code>(source, responseEventType, apiHost?, apiPort?)</code> Initializes the base <code>WorkerBase&lt;JsonNode, JsonObject&gt;</code> and (optionally) creates an <code>ApiClient</code> at <code>apiHost:apiPort</code>. <code>HandleAsync(CloudEvent, JsonNode) → Task&lt;JsonObject?&gt;</code> Abstract — override to process events with pre-configured API access. <code>Api : ApiClient?</code> The configured client for calling backend services; <code>null</code> until <code>EnsureClient(...)</code> is called if the lazy ctor was used. <pre><code>using System.Text.Json.Nodes;
using CloudNative.CloudEvents;
using Virtufin.Api.Client;
using Virtufin.Worker.DevKit;

public class MyApiWorker : ApiWorker
{
    public MyApiWorker()
        : base(new Uri("urn:my-api-worker"), "my.response",
               apiHost: "localhost", apiPort: 5002) { }

    protected override async Task&lt;JsonObject?&gt; HandleAsync(
        CloudEvent input, JsonNode node)
    {
        var result = await Api!.Gateway.targetservice.SomeMethodAsync(
            new Dictionary&lt;string, object?&gt; { ["key"] = "value" });
        return Response(input, "process", true, message: $"Result: {result}");
    }
}
</code></pre>

